import heapq
from collections import Counter


def _dependency_solver(data, order, maximize, feature_aware):
    packages = data["packages"]
    names = sorted(packages, reverse=(order == "descending"))
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]

    options = {}
    for name in packages:
        versions = [row["version"] for row in packages[name]
                    if row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
        options[name] = [None] + versions

    best_key = None
    best = None
    for values in product(*(options[name] for name in packages)):
        chosen = dict(zip(packages, values))
        if any(chosen.get(name) is None
               or not bounds[0] <= chosen[name] <= bounds[1]
               for name, bounds in roots.items()):
            continue

        rows = {}
        for name, version in chosen.items():
            if version is not None:
                rows[name] = next(row for row in packages[name]
                                  if row["version"] == version)

        edges = {name: [] for name in rows}
        valid = True
        for name, row in rows.items():
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and (not feature_aware or feature not in features):
                    continue
                target = chosen.get(dep["name"])
                if target is None or not dep["min"] <= target <= dep["max"]:
                    valid = False
                    break
                edges[name].append(dep["name"])
            if not valid:
                break
        if not valid:
            continue

        # Installed packages must be precisely the active closure of the roots.
        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(edges[name])
        if reachable != set(rows):
            continue

        finished, active = set(), set()
        def acyclic(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not acyclic(other) for other in edges[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True
        if not all(acyclic(name) for name in rows):
            continue

        key = tuple(-1 if chosen[name] is None else chosen[name] for name in names)
        if best_key is None or (key > best_key if maximize else key < best_key):
            best_key = key
            best = {name: version for name, version in chosen.items()
                    if version is not None}

    return {"error": "unsatisfiable"} if best is None else {"versions": best}


def _build_component_01():
    return lambda data: _dependency_solver(data, "ascending", True, True)


